			inner := NewMapPrelim()
			txt := NewTextPrelim()
			txt.Insert(txn, 0, "leaf", nil)
			inner.Set(txn, "text", txt)
			list := NewArrayPrelim()
			list.Push(txn, []any{"one", "two"})
			inner.Set(txn, "list", list)
			outer.Set(txn, "inner", inner)
			outer.Set(txn, "tag", "o")
